insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000995321','40000000-0000-4000-8000-000000099532','Leia o objetivo','Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.',1),('70000000-0000-4000-8000-000000995322','40000000-0000-4000-8000-000000099532','Reconheça a ideia','Há um produto: derivar $x$ o simplifica e integrar $e^{4x}$ é direto.',2),('70000000-0000-4000-8000-000000995323','40000000-0000-4000-8000-000000099532','Escreva a relação','Registre a definição, fórmula ou teste que se aplica antes de simplificar.',3),('70000000-0000-4000-8000-000000995324','40000000-0000-4000-8000-000000099532','Desenvolva a análise','Execute a transformação necessária e obtenha: $e^{4x}\left(\frac{x}{4}-\frac{1}{16}\right)+C$',4),('70000000-0000-4000-8000-000000995325','40000000-0000-4000-8000-000000099532','Confira a conclusão','Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.',5) on conflict (id) do update set question_id=excluded.question_id,title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
