insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000995391','40000000-0000-4000-8000-000000099539','Nomeie primeiro a ideia central: O denominador possui dois fatores lineares distintos; decomponha a fração antes de integrar.',1),('60000000-0000-4000-8000-000000995392','40000000-0000-4000-8000-000000099539','Escreva a definição ou a relação escolhida antes de substituir os dados.',2),('60000000-0000-4000-8000-000000995393','40000000-0000-4000-8000-000000099539','Ao final, teste se o resultado preserva as condições do enunciado e descarte erros de sinal, domínio ou hipótese.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099539','$\frac{1}{2}\ln\left|\frac{x}{x+2}\right|+C$','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. O denominador possui dois fatores lineares distintos; decomponha a fração antes de integrar. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000995391','40000000-0000-4000-8000-000000099539','Leia o objetivo','Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.',1),('70000000-0000-4000-8000-000000995392','40000000-0000-4000-8000-000000099539','Reconheça a ideia','O denominador possui dois fatores lineares distintos; decomponha a fração antes de integrar.',2),('70000000-0000-4000-8000-000000995393','40000000-0000-4000-8000-000000099539','Escreva a relação','Registre a definição, fórmula ou teste que se aplica antes de simplificar.',3),('70000000-0000-4000-8000-000000995394','40000000-0000-4000-8000-000000099539','Desenvolva a análise','Execute a transformação necessária e obtenha: $\frac{1}{2}\ln\left|\frac{x}{x+2}\right|+C$',4),('70000000-0000-4000-8000-000000995395','40000000-0000-4000-8000-000000099539','Confira a conclusão','Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.',5) on conflict (id) do update set question_id=excluded.question_id,title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
